{"command": "node --input-type=module - <<'NODE'
import * as ecc from 'tiny-secp256k1';
import { initEccLib } from './src/cjs/ecc_lib.cjs';
import { p2tr } from './src/cjs/payments/p2tr.cjs';
import { testnet } from './src/cjs/networks.cjs';
initEccLib(ecc);
const h=x=>Uint8Array.from(Buffer.from(x,'hex')), x=b=>Buffer.from(b).toString('hex');
const PK=h('ab610d22c801def8a1e02368d1b92018970eb52a729919705e8a1a2f60c750f5');
let p=p2tr({pubkey:PK,network:testnet}); console.log('testnet',p.address,p.network===testnet,p.output&&x(p.output));
const internal=h('ee4fe085983462a184015d1f782d6a5f8b9c2b60130aff050ce221ecf3786592');
const a=h('387671353e273264c495656e27e39ba899ea8fee3bb69fb2a680e22093447d48ac');
const b=h('424950333431');
const tree=[{output:a,version:0xc0},{output:b,version:0x98}];
for(const red of [{output:a,redeemVersion:0xc0},{output:b,redeemVersion:0x98}]) {
 const q=p2tr({internalPubkey:internal, redeem:red, scriptTree:tree});
 console.log('q',x(q.pubkey),q.address,x(q.hash),q.redeemVersion,q.witness.map(x));
}
const q=p2tr({internalPubkey:internal, redeem:{output:a,redeemVersion:0xc0}, scriptTree:tree}, {validate:false});
console.log('q2',q.witness?.map(x));
NODE"}

