describe('p2tr input requirements and schema validation', () => {
  test('throws when no usable identifying data is supplied', () => {
    expect(() => p2tr({})).toThrow(new TypeError('Not enough data'));
    expect(() => p2tr({ signature: SIGNATURE })).toThrow(
      new TypeError('Not enough data'),
    );
    expect(() => p2tr({ witness: [SIGNATURE] })).toThrow(
      new TypeError('Not enough data'),
    );
  });

  test('rejects wrongly sized buffers and non-buffer witness elements', () => {
    expect(() => p2tr({ pubkey: H('ab') })).toThrow();
    expect(() => p2tr({ pubkey: PUBKEY, output: new Uint8Array(33) })).toThrow();
    expect(() => p2tr({ pubkey: PUBKEY, hash: new Uint8Array(31) })).toThrow();
    expect(() =>
      p2tr({ pubkey: PUBKEY, witness: [SIGNATURE.slice(0, 63)] }),
    ).toThrow();
    expect(() => p2tr({ pubkey: PUBKEY, witness: ['not-bytes'] })).toThrow();
