describe('derivation from a public key, output, address, and network', () => {
  test('derives the mainnet address and P2TR output from a pubkey', () => {
    const payment = p2tr({ pubkey: PUBKEY });

    expect(payment.name).toBe('p2tr');
    expect(payment.network).toBe(bitcoin);
    expect(payment.address).toBe(ADDRESS);
    expect(hexOf(payment.pubkey)).toBe(PUBKEY_HEX);
    expect(hexOf(payment.output)).toBe('5120' + PUBKEY_HEX);
    expect(payment.signature).toBeUndefined();
    expect(payment.witness).toBeUndefined();
  });

  test('derives the pubkey and output from a mainnet address', () => {
    const payment = p2tr({ address: ADDRESS });

    expect(payment.address).toBe(ADDRESS);
    expect(hexOf(payment.pubkey)).toBe(PUBKEY_HEX);
    expect(hexOf(payment.output)).toBe('5120' + PUBKEY_HEX);
  });

  test('derives the address and pubkey from a P2TR output script', () => {
    const payment = p2tr({ output: OUTPUT });

