describe('key-path witnesses', () => {
  test('constructs a key-path witness from a signature', () => {
    const payment = p2tr({ pubkey: PUBKEY, signature: SIGNATURE });

    expect(payment.witness).toHaveLength(1);
    expect(hexOf(payment.witness[0])).toBe(hexOf(SIGNATURE));
    expect(payment.signature).toBe(SIGNATURE);
  });

  test('extracts a signature from a supplied key-path witness', () => {
    const witness = [SIGNATURE];
    const payment = p2tr({ pubkey: PUBKEY, witness });

    expect(payment.witness).toBe(witness);
    expect(hexOf(payment.signature)).toBe(hexOf(SIGNATURE));
  });

