    expect(payment.witness).toHaveLength(2);
    expect(hexOf(payment.witness[1])).toBe(hexOf(ANNEX));
  });

  test('rejects a signature that disagrees with a key-path witness', () => {
    expect(() =>
      p2tr({
        pubkey: PUBKEY,
        signature: SIGNATURE,
        witness: [new Uint8Array(64)],
      }),
    ).toThrow(new TypeError('Signature mismatch'));
  });
});

describe('script trees and constructed script-path witnesses', () => {
  test('constructs the witness for the first leaf, including its control block', () => {
    const payment = p2tr({
      internalPubkey: TREE_INTERNAL,
      redeem: { output: LEAF_A, redeemVersion: 0xc0 },
      scriptTree: SCRIPT_TREE,
    });

    expect(payment.redeemVersion).toBe(0xc0);
    expect(hexOf(payment.hash)).toBe(TREE_HASH);
    expect(hexOf(payment.pubkey)).toBe(TREE_PUBKEY);
    expect(payment.address).toBe(TREE_ADDRESS);
    expect(payment.witness).toHaveLength(2);
    expect(hexOf(payment.witness[0])).toBe(hexOf(LEAF_A));
    expect(hexOf(payment.witness[1])).toBe(hexOf(CONTROL_A));
  });

  test('constructs the witness for a non-default leaf version', () => {
    const payment = p2tr({
      internalPubkey: TREE_INTERNAL,
      redeem: { output: LEAF_B, redeemVersion: 0x98 },
      scriptTree: SCRIPT_TREE,
    });

    expect(payment.redeemVersion).toBe(0x98);
    expect(hexOf(payment.witness[0])).toBe(hexOf(LEAF_B));
    expect(hexOf(payment.witness[1])).toBe(hexOf(CONTROL_B));
    expect(payment.witness[1][0]).toBe(0x98);
  });

  test('constructs a path-less witness from a hash and matching redeem script', () => {
    const payment = p2tr({
      internalPubkey: HASH_ONLY_INTERNAL,
      redeem: { output: HASH_ONLY_SCRIPT },
      hash: H(HASH_ONLY_ROOT),
    });

    expect(hexOf(payment.hash)).toBe(HASH_ONLY_ROOT);
    expect(payment.witness).toHaveLength(2);
    expect(hexOf(payment.witness[0])).toBe(hexOf(HASH_ONLY_SCRIPT));
    expect(hexOf(payment.witness[1])).toBe(
      'c0' + hexOf(HASH_ONLY_INTERNAL),
    );
  });

  test('uses the top-level redeemVersion before the redeem and default values', () => {
    expect(
      p2tr({ internalPubkey: TREE_INTERNAL }, { validate: false })
        .redeemVersion,
    ).toBe(0xc0);
    expect(
      p2tr(
        {
          internalPubkey: TREE_INTERNAL,
          redeem: { output: LEAF_A, redeemVersion: 0xc0 },
        },
        { validate: false },
      ).redeemVersion,
    ).toBe(0xc0);
    expect(
      p2tr(
        {
          internalPubkey: TREE_INTERNAL,
          redeem: { output: LEAF_A, redeemVersion: 0xc0 },
          redeemVersion: 0xaa,
        },
        { validate: false },
      ).redeemVersion,
    ).toBe(0xaa);
  });

  test('omits a constructed witness when the redeem script is not in the tree', () => {
    const payment = p2tr(
      {
        internalPubkey: TREE_INTERNAL,
        redeem: { output: H('51') },
        scriptTree: SCRIPT_TREE,
      },
      { validate: false },
    );

    expect(payment.witness).toBeUndefined();
  });

  test('rejects a merkle root that does not match the script tree', () => {
    expect(() =>
      p2tr({
        internalPubkey: SINGLE_LEAF_INTERNAL,
        scriptTree: { output: SINGLE_LEAF_SCRIPT },
        hash: new Uint8Array(32),
      }),
    ).toThrow(new TypeError('Hash mismatch'));
  });

  test('rejects a redeem script that is not present in the tree', () => {
    expect(() =>
      p2tr({
        internalPubkey: SINGLE_LEAF_INTERNAL,
        scriptTree: { output: SINGLE_LEAF_SCRIPT },
        redeem: { output: H('51') },
      }),
    ).toThrow(new TypeError('Redeem script not in tree'));
  });
});

describe('derivation from script-path witnesses', () => {
  test('derives the output key, address, and merkle root from a witness', () => {
    const payment = p2tr({ witness: WITNESS_A });

    expect(hexOf(payment.internalPubkey)).toBe(hexOf(TREE_INTERNAL));
    expect(hexOf(payment.pubkey)).toBe(TREE_PUBKEY);
    expect(payment.address).toBe(TREE_ADDRESS);
    expect(hexOf(payment.output)).toBe('5120' + TREE_PUBKEY);
    expect(hexOf(payment.hash)).toBe(TREE_HASH);
    expect(payment.signature).toBeUndefined();
  });

  test('reconstructs the redeem script, stack, and leaf version', () => {
    const stackItem = H('010203');
    const payment = p2tr({ witness: [stackItem, LEAF_A, CONTROL_A] });

    expect(hexOf(payment.redeem.output)).toBe(hexOf(LEAF_A));
    expect(payment.redeem.witness).toHaveLength(1);
    expect(hexOf(payment.redeem.witness[0])).toBe(hexOf(stackItem));
    expect(payment.redeem.redeemVersion).toBe(0xc0);
    expect(payment.redeemVersion).toBe(0xc0);
  });

  test('removes an annex from script-path derivation while preserving it in witness', () => {
    const witness = [LEAF_A, CONTROL_A, ANNEX];
    const payment = p2tr({ witness });

    expect(hexOf(payment.internalPubkey)).toBe(hexOf(TREE_INTERNAL));
    expect(hexOf(payment.hash)).toBe(TREE_HASH);
    expect(hexOf(payment.redeem.output)).toBe(hexOf(LEAF_A));
    expect(payment.witness).toBe(witness);
    expect(payment.witness).toHaveLength(3);
  });
});

describe('extended validation', () => {
  test('rejects a pubkey with no valid x-only point', () => {
    expect(() =>
      p2tr({
        pubkey: H(
          'f136e956540197c21ff3c075d32a6e3c82f1ee1e646cc0f08f51b0b5edafa762',
        ),
      }),
    ).toThrow(new TypeError('Invalid pubkey for p2tr'));
  });

  test('rejects an output script without OP_1 and a 32-byte push', () => {
    const wrongVersion = concat(
      Uint8Array.of(0x00, 0x20),
      PUBKEY,
    );
    const wrongPushOpcode = concat(
      Uint8Array.of(0x51, 0x21),
      PUBKEY.slice(0, 31),
    );

    expect(() => p2tr({ output: wrongVersion })).toThrow(
      new TypeError('Output is invalid'),
    );
    expect(wrongPushOpcode).toHaveLength(34);
    expect(() => p2tr({ output: wrongPushOpcode })).toThrow(
      new TypeError('Output is invalid'),
    );
  });

  test('rejects mismatched pubkey, output, and address combinations', () => {
    expect(() =>
      p2tr({ pubkey: PUBKEY, output: p2trScript(MISMATCHED_PUBKEY) }),
    ).toThrow(new TypeError('Pubkey mismatch'));
    expect(() => p2tr({ pubkey: PUBKEY, address: MISMATCHED_ADDRESS })).toThrow(
      new TypeError('Pubkey mismatch'),
    );
    expect(() =>
      p2tr({ output: OUTPUT, address: MISMATCHED_ADDRESS }),
    ).toThrow(new TypeError('Pubkey mismatch'));
  });

  test('rejects a supplied pubkey that differs from the tweaked internal key', () => {
    expect(() =>
      p2tr({ internalPubkey: BIP86_INTERNAL, pubkey: PUBKEY }),
    ).toThrow(new TypeError('Pubkey mismatch'));
  });

  test('rejects addresses for another network, version, or payload length', () => {
    expect(() => p2tr({ address: TESTNET_ADDRESS })).toThrow(
      new TypeError('Invalid prefix or Network mismatch'),
    );
    expect(() =>
      p2tr({
        address:
          'bc1z4dss6gkgq8003g0qyd5drwfqrztsadf2w2v3juz73gdz7cx82r6s6rxhwd',
      }),
    ).toThrow(new TypeError('Invalid address version'));
    expect(() =>
      p2tr({
        address:
          'bc1p4dss6gkgq8003g0qyd5drwfqrztsadf2w2v3juz73gdz7cx82qh3d2w3',
      }),
    ).toThrow(new TypeError('Invalid address data'));
  });

  test('validates control-block length and merkle-path shape', () => {
    expect(() => p2tr({ witness: [LEAF_A, new Uint8Array(16)] })).toThrow(
      new TypeError(
        'The control-block length is too small. Got 16, expected min 33.',
      ),
    );
    expect(() => p2tr({ witness: [LEAF_A, new Uint8Array(40)] })).toThrow(
      new TypeError('The control-block length of 40 is incorrect!'),
    );
    expect(() =>
      p2tr({ witness: [LEAF_A, new Uint8Array(33 + 32 * 129)] }),
    ).toThrow(
      new TypeError('The script path is too long. Got 129, expected max 128.'),
    );
  });

  test('rejects an invalid or inconsistent internal key in the control block', () => {
    const zeroInternal = concat(Uint8Array.of(0xc0), new Uint8Array(32));

    expect(() => p2tr({ witness: [LEAF_A, zeroInternal] })).toThrow(
      new TypeError('Invalid internalPubkey for p2tr witness'),
    );
    expect(() =>
      p2tr({ witness: WITNESS_A, internalPubkey: PUBKEY }),
    ).toThrow(new TypeError('Internal pubkey mismatch'));
  });

  test('rejects a witness whose output key or parity disagrees with metadata', () => {
    expect(() =>
      p2tr({ witness: WITNESS_A, pubkey: PUBKEY }),
    ).toThrow(new TypeError('Pubkey mismatch for p2tr witness'));

    const wrongParityControl = CONTROL_A.slice();
    wrongParityControl[0] = 0xc1;
    expect(() =>
      p2tr({ witness: [LEAF_A, wrongParityControl] }),
    ).toThrow(new Error('Incorrect parity'));
  });

  test('rejects inconsistent redeem version, output, witness, or empty output', () => {
    expect(() =>
      p2tr({
        witness: WITNESS_A,
        redeem: { output: LEAF_A, redeemVersion: 0x98 },
      }),
    ).toThrow(new TypeError('Redeem.redeemVersion and witness mismatch'));

    expect(() =>
      p2tr({
        witness: WITNESS_A,
        redeem: { output: LEAF_B, redeemVersion: 0xc0 },
      }),
    ).toThrow(new TypeError('Redeem.output and witness mismatch'));

    expect(() =>
      p2tr({
        witness: [H('010203'), LEAF_A, CONTROL_A],
        redeem: {
          output: LEAF_A,
          redeemVersion: 0xc0,
          witness: [H('040506')],
        },
      }),
    ).toThrow(new TypeError('Redeem.witness and witness mismatch'));

    expect(() =>
      p2tr({
        witness: WITNESS_A,
        redeem: { output: new Uint8Array(0), redeemVersion: 0xc0 },
      }),
    ).toThrow(new TypeError('Redeem.output is invalid'));
  });

  test('fails only when validation requires an ECC library', () => {
    initEccLib(undefined);
    try {
      const unchecked = p2tr({ pubkey: PUBKEY }, { validate: false });
      expect(unchecked.address).toBe(ADDRESS);
      expect(() => p2tr({ pubkey: PUBKEY })).toThrow(
        /No ECC Library provided/,
      );
    } finally {
      initEccLib(ecc);
    }
  });
});
