{"command": "cd /testbed && node -e "
const {Transaction}=require('./src/cjs/transaction.cjs');
const h=s=>Uint8Array.from(Buffer.from(s,'hex'));
const to=b=>Buffer.from(b).toString('hex');
const tx=new Transaction(); const hash=new Uint8Array(32).fill(1);
tx.addInput(hash,0); tx.addOutput(h('51'),1000n); tx.addInput(new Uint8Array(32).fill(2),1); tx.addOutput(h('52'),2000n);
const base=tx.hashForSignature(0, h('51'), 1);
console.log('ALL', to(base));
console.log('NONE', to(tx.hashForSignature(0,h('51'),2)));
console.log('SINGLE', to(tx.hashForSignature(0,h('51'),3)));
console.log('ACP', to(tx.hashForSignature(0,h('51'),0x81)));
console.log('SINGLE oob', to(tx.hashForSignature(5,h('51'),3)));
console.log('NONE|ACP', to(tx.hashForSignature(0,h('51'),0x82)));
// hashType 0 vs 1 differ
console.log('type0 differs', to(tx.hashForSignature(0,h('51'),0))!==to(base));
// adding input changes ALL but not ACP
const clone=tx.clone(); clone.addInput(new Uint8Array(32).fill(3),2);
console.log('ALL changes adding input', to(clone.hashForSignature(0,h('51'),1))!==to(base));
console.log('ACP unchanged adding input', to(clone.hashForSignature(0,h('51'),0x81))===to(tx.hashForSignature(0,h('51'),0x81)));
// errors
for(const [name,fn] of [
 ['addInput short',()=>tx.addInput(new Uint8Array(31),0)],
 ['addInput neg idx',()=>tx.addInput(hash,-1)],
 ['addOutput neg',()=>tx.addOutput(h('51'),-1n)],
 ['addOutput too big',()=>tx.addOutput(h('51'),9223372036854775808n)],
 ['addOutput wrong script',()=>tx.addOutput('x',1n)],
 ['setInputScript wrong',()=>tx.setInputScript(0,'x')],
 ['setWitness wrong',()=>tx.setWitness(0,'x')],
 ['isCoinbaseHash wrong',()=>Transaction.isCoinbaseHash(new Uint8Array(31))],
 ['hfs neg',()=>tx.hashForSignature(-1,h('51'),1)],
 ['v0 neg value',()=>tx.hashForWitnessV0(0,h('51'),-1n,1)],
 ['v1 mismatch',()=>tx.hashForWitnessV1(0,[h('51')],[1000n],1)],
]){try{fn();console.log(name,'NO THROW')}catch(e){console.log(name,'throws:',e.message.slice(0,70))}}
// v1 no outputs
const noOut=new Transaction(); noOut.addInput(hash,0);
try{noOut.hashForWitnessV1(0,[h('51')],[1000n],0);console.log('v1 noouts NO THROW')}catch(e){console.log('v1 noouts throws:',e.message)}
// annex/leaf
const v1=tx.hashForWitnessV1(0,[h('51'),h('52')],[1000n,2000n],0);
const v1annex=tx.hashForWitnessV1(0,[h('51'),h('52')],[1000n,2000n],0,undefined,h('50'));
const v1leaf=tx.hashForWitnessV1(0,[h('51'),h('52')],[1000n,2000n],0,new Uint8Array(32).fill(9));
console.log('v1 lens',v1.length,v1annex.length,v1leaf.length,'diff',to(v1)!==to(v1annex),to(v1)!==to(v1leaf));
""}

