describe('Transaction constants', () => {
  test('exposes the documented static values', () => {
    expect(Transaction.DEFAULT_SEQUENCE).toBe(4294967295);
    expect(Transaction.SIGHASH_DEFAULT).toBe(0);
    expect(Transaction.SIGHASH_ALL).toBe(1);
    expect(Transaction.SIGHASH_NONE).toBe(2);
    expect(Transaction.SIGHASH_SINGLE).toBe(3);
    expect(Transaction.SIGHASH_ANYONECANPAY).toBe(128);
    expect(Transaction.SIGHASH_OUTPUT_MASK).toBe(3);
    expect(Transaction.SIGHASH_INPUT_MASK).toBe(128);
    expect(Transaction.ADVANCED_TRANSACTION_MARKER).toBe(0);
    expect(Transaction.ADVANCED_TRANSACTION_FLAG).toBe(1);
  });
});

describe('construction and input/output management', () => {
  test('initializes an empty transaction with default version and locktime', () => {
    const tx = new Transaction();
    expect(tx.version).toBe(1);
    expect(tx.locktime).toBe(0);
    expect(tx.ins).toEqual([]);
    expect(tx.outs).toEqual([]);
    expect(tx.hasWitnesses()).toBe(false);
    expect(tx.isCoinbase()).toBe(false);
  });

  test('addInput returns an index and applies defaults', () => {
    const tx = new Transaction();
    const index = tx.addInput(hashOf(0x22), 7);

    expect(index).toBe(0);
    expect(tx.ins).toHaveLength(1);
    expect(tx.ins[0].hash).toEqual(hashOf(0x22));
    expect(tx.ins[0].index).toBe(7);
    expect(tx.ins[0].script).toEqual(EMPTY);
    expect(tx.ins[0].sequence).toBe(Transaction.DEFAULT_SEQUENCE);
    expect(tx.ins[0].witness).toEqual([]);
  });

  test('addInput honors an explicit sequence and scriptSig', () => {
    const tx = new Transaction();
    const scriptSig = fromASM('OP_0 OP_1');
    const index = tx.addInput(hashOf(0x33), 2, 0xfffffffe, scriptSig);

    expect(index).toBe(0);
    expect(tx.ins[0].sequence).toBe(0xfffffffe);
    expect(tx.ins[0].script).toEqual(scriptSig);
  });

  test('addOutput returns an index and stores script and value', () => {
    const tx = new Transaction();
    const script = fromASM('OP_DUP OP_HASH160 00112233445566778899aabbccddeeff00112233 OP_EQUALVERIFY OP_CHECKSIG');

    expect(tx.addOutput(script, 123456789n)).toBe(0);
    expect(tx.addOutput(EMPTY, 0n)).toBe(1);
    expect(tx.outs[0].script).toEqual(script);
    expect(tx.outs[0].value).toBe(123456789n);
    expect(tx.outs[1].value).toBe(0n);
  });

  test('setInputScript replaces the input script', () => {
    const tx = makeSimpleTx();
    const scriptSig = fromASM('OP_1 OP_2');
    tx.setInputScript(0, scriptSig);
    expect(tx.ins[0].script).toEqual(scriptSig);
  });

  test('setWitness stores a witness stack', () => {
    const tx = makeSimpleTx();
    const stack = [bytes('0102'), bytes('aabbcc')];
    tx.setWitness(0, stack);
    expect(tx.ins[0].witness).toEqual(stack);
    expect(tx.hasWitnesses()).toBe(true);
  });
});

describe('serialization and parsing', () => {
  test('serializes an empty-script transaction to the expected bytes', () => {
    const tx = makeSimpleTx();
    expect(hex(tx.toBuffer())).toBe(SIMPLE_TX_HEX);
    expect(tx.toHex()).toBe(SIMPLE_TX_HEX);
    expect(tx.getId()).toBe(hex(tx.getHash(false)).match(/.{2}/g).reverse().join(''));
  });

  test('round-trips through hex, preserving transaction fields', () => {
    const tx = new Transaction();
    tx.version = 2;
    tx.locktime = 500000;
    tx.addInput(hashOf(0x07), 3, 0xfffffffe, bytes('51'));
    tx.addOutput(
      fromASM('OP_DUP OP_HASH160 0000000000000000000000000000000000000000 OP_EQUALVERIFY OP_CHECKSIG'),
      123456789n,
    );

    const parsed = Transaction.fromHex(tx.toHex());

    expect(parsed.version).toBe(2);
    expect(parsed.locktime).toBe(500000);
    expect(parsed.ins[0].index).toBe(3);
    expect(parsed.ins[0].sequence).toBe(0xfffffffe);
    expect(hex(parsed.ins[0].script)).toBe('51');
    expect(parsed.outs[0].value).toBe(123456789n);
    expect(parsed.toHex()).toBe(tx.toHex());
  });

  test('fromBuffer accepts the same bytes as fromHex', () => {
    const parsed = Transaction.fromBuffer(bytes(SIMPLE_TX_HEX));
    expect(parsed.toHex()).toBe(SIMPLE_TX_HEX);
  });

  test('toBuffer writes at an initial offset and returns only the written slice', () => {
    const tx = makeSimpleTx();
    const raw = tx.toBuffer();
    const target = new Uint8Array(raw.length + 8).fill(0xaa);

    const written = tx.toBuffer(target, 4);

    expect(hex(written)).toBe(SIMPLE_TX_HEX);
    expect(written).toHaveLength(raw.length);
    expect(target.subarray(0, 4)).toEqual(new Uint8Array([0xaa, 0xaa, 0xaa, 0xaa]));
    expect(target.subarray(4 + raw.length)).toEqual(new Uint8Array([0xaa, 0xaa, 0xaa, 0xaa]));
  });

  test('strict parsing rejects unexpected trailing data', () => {
    expect(() => Transaction.fromHex(SIMPLE_TX_HEX + '00')).toThrow(
      'Transaction has unexpected data',
    );
  });

  test('fromBuffer with _NO_STRICT ignores trailing data', () => {
    const parsed = Transaction.fromBuffer(bytes(SIMPLE_TX_HEX + '00'), true);
    expect(parsed.toHex()).toBe(SIMPLE_TX_HEX);
  });

  test('parses a real signed transaction with its known id', () => {
    const tx = Transaction.fromHex(STANDARD_TX_HEX);
    expect(tx.ins).toHaveLength(1);
    expect(tx.outs).toHaveLength(1);
    expect(tx.outs[0].value).toBe(100000n);
    expect(tx.getId()).toBe('a0ff943d3f644d8832b1fa74be4d0ad2577615dc28a7ef74ff8c271b603a082a');
  });
});
