describe('witness handling and size accounting', () => {
  test('serializes the segwit marker, flag, and witness stack', () => {
    const tx = makeSimpleTx();
    tx.setWitness(0, [bytes('0102')]);

    expect(tx.hasWitnesses()).toBe(true);
    expect(tx.toHex()).toBe(SIMPLE_WITNESS_TX_HEX);

    const parsed = Transaction.fromHex(SIMPLE_WITNESS_TX_HEX);
    expect(parsed.ins[0].witness).toEqual([bytes('0102')]);
    expect(parsed.hasWitnesses()).toBe(true);
  });

  test('stripWitnesses removes witness data and returns to legacy serialization', () => {
    const tx = makeSimpleTx();
    tx.setWitness(0, [bytes('0102'), bytes('03')]);
    expect(tx.hasWitnesses()).toBe(true);

    tx.stripWitnesses();

    expect(tx.hasWitnesses()).toBe(false);
    expect(tx.ins[0].witness).toEqual([]);
    expect(tx.toHex()).toBe(SIMPLE_TX_HEX);
  });

  test('byteLength, weight, and virtualSize reflect witness data', () => {
    const legacy = makeSimpleTx();
    expect(legacy.byteLength(false)).toBe(60);
    expect(legacy.byteLength(true)).toBe(60);
    expect(legacy.weight()).toBe(240);
    expect(legacy.virtualSize()).toBe(60);

    legacy.setWitness(0, [bytes('0102')]);

    expect(legacy.byteLength(false)).toBe(60);
    expect(legacy.byteLength(true)).toBe(66);
