describe('input and output validation', () => {
  test.each([
    ['a 31-byte input hash', () => new Transaction().addInput(new Uint8Array(31), 0)],
    ['a negative input index', () => new Transaction().addInput(hashOf(1), -1)],
    ['an input index above uint32', () => new Transaction().addInput(hashOf(1), 0x100000000)],
    ['a negative sequence', () => new Transaction().addInput(hashOf(1), 0, -1)],
    ['a non-byte scriptSig', () => new Transaction().addInput(hashOf(1), 0, undefined, '51')],
  ])('rejects %s', (_label, call) => {
    expect(call).toThrow();
  });

  test.each([
    ['a non-byte output script', () => new Transaction().addOutput('51', 1n)],
    ['a negative output value', () => new Transaction().addOutput(EMPTY, -1n)],
    ['an output value above int64 max', () => new Transaction().addOutput(EMPTY, 9223372036854775808n)],
  ])('rejects %s', (_label, call) => {
    expect(call).toThrow();
  });

  test('setInputScript and setWitness validate their arguments', () => {
    const tx = makeSimpleTx();
    expect(() => tx.setInputScript(0, '51')).toThrow();
    expect(() => tx.setWitness(0, 'not-an-array')).toThrow();
    expect(() => tx.setWitness(0, ['not-bytes'])).toThrow();
  });
});

describe('hashForSignature', () => {
  const scriptWithOp3 = fromASM('OP_0 OP_3');
  const scriptWithSeparator = fromASM('OP_0 OP_CODESEPARATOR OP_3');
  const scriptWithSeparatorAndOp4 = fromASM('OP_0 OP_CODESEPARATOR OP_4');

  test('matches the known legacy sighash vector', () => {
    const tx = Transaction.fromHex(SIGHASH_TX_HEX);
    expect(hex(tx.hashForSignature(0, scriptWithOp3, 0))).toBe(
      '3d56a632462b9fc9b89eeddcad7dbe476297f34aff7e5f9320e2a99fb5e97136',
    );
  });

  test('strips OP_CODESEPARATOR before hashing the previous output script', () => {
    const tx = Transaction.fromHex(SIGHASH_TX_HEX);
    expect(hex(tx.hashForSignature(0, scriptWithSeparator, 0))).toBe(
      hex(tx.hashForSignature(0, scriptWithOp3, 0)),
    );
  });

  test('does not strip opcodes other than OP_CODESEPARATOR', () => {
    const tx = Transaction.fromHex(SIGHASH_TX_HEX);
    expect(hex(tx.hashForSignature(0, scriptWithSeparatorAndOp4, 0))).toBe(
      'fa075877cb54916236806a6562e4a8cdad48adf1268e73d72d1f9fdd867df463',
    );
  });

  test('returns the ONE sentinel for an out-of-range input index', () => {
    const tx = Transaction.fromHex(SIGHASH_TX_HEX);
    expect(tx.hashForSignature(2, fromASM('OP_0'), 0)).toEqual(ONE_HASH);
  });

  test('returns the ONE sentinel for SIGHASH_SINGLE without a matching output', () => {
    const tx = Transaction.fromHex(SIGHASH_TX_HEX);
    expect(tx.hashForSignature(1, fromASM('OP_0'), Transaction.SIGHASH_SINGLE)).toEqual(
      ONE_HASH,
    );
  });

  test('produces distinct 32-byte hashes for different hash types', () => {
    const tx = Transaction.fromHex(SIGHASH_TX_HEX);
    const script = fromASM('OP_0');
    const hashTypes = [
      Transaction.SIGHASH_DEFAULT,
      Transaction.SIGHASH_ALL,
      Transaction.SIGHASH_NONE,
      Transaction.SIGHASH_SINGLE,
      Transaction.SIGHASH_ALL | Transaction.SIGHASH_ANYONECANPAY,
      Transaction.SIGHASH_NONE | Transaction.SIGHASH_ANYONECANPAY,
      Transaction.SIGHASH_SINGLE | Transaction.SIGHASH_ANYONECANPAY,
    ];

    const hashes = hashTypes.map(type => hex(tx.hashForSignature(0, script, type)));

    expect(hashes.every(hashValue => hashValue.length === 64)).toBe(true);
    expect(new Set(hashes).size).toBe(hashTypes.length);
  });

  test('SIGHASH_ANYONECANPAY ignores additional inputs', () => {
    const tx = Transaction.fromHex(SIGHASH_TX_HEX);
    const script = fromASM('OP_0');

    const allBefore = hex(tx.hashForSignature(0, script, Transaction.SIGHASH_ALL));
    const anyoneCanPayBefore = hex(
      tx.hashForSignature(
        0,
        script,
        Transaction.SIGHASH_ALL | Transaction.SIGHASH_ANYONECANPAY,
      ),
    );

    tx.addInput(hashOf(0x09), 0);

    expect(
      hex(
        tx.hashForSignature(
          0,
          script,
          Transaction.SIGHASH_ALL | Transaction.SIGHASH_ANYONECANPAY,
        ),
      ),
    ).toBe(anyoneCanPayBefore);
    expect(hex(tx.hashForSignature(0, script, Transaction.SIGHASH_ALL))).not.toBe(
      allBefore,
    );
  });

  test('validates the input index and previous output script', () => {
    const tx = Transaction.fromHex(SIGHASH_TX_HEX);
    expect(() => tx.hashForSignature(-1, fromASM('OP_0'), 1)).toThrow();
    expect(() => tx.hashForSignature(0, 'not-bytes', 1)).toThrow();
  });
});

