describe('Transaction construction and mutators', () => {
  test('starts with documented defaults and exposes protocol constants', () => {
    const tx = new Transaction();

    expect(tx.version).toBe(1);
    expect(tx.locktime).toBe(0);
    expect(tx.ins).toEqual([]);
    expect(tx.outs).toEqual([]);
    expect(Transaction.DEFAULT_SEQUENCE).toBe(0xffffffff);
    expect(Transaction.SIGHASH_DEFAULT).toBe(0x00);
    expect(Transaction.SIGHASH_ALL).toBe(0x01);
    expect(Transaction.SIGHASH_NONE).toBe(0x02);
    expect(Transaction.SIGHASH_SINGLE).toBe(0x03);
    expect(Transaction.SIGHASH_ANYONECANPAY).toBe(0x80);
    expect(Transaction.SIGHASH_OUTPUT_MASK).toBe(0x03);
    expect(Transaction.SIGHASH_INPUT_MASK).toBe(0x80);
    expect(Transaction.ADVANCED_TRANSACTION_MARKER).toBe(0x00);
    expect(Transaction.ADVANCED_TRANSACTION_FLAG).toBe(0x01);
  });

  test('addInput stores input data, defaults optional fields, and returns its index', () => {
    const tx = new Transaction();
    const hash = h('ab'.repeat(32));
    const script = h('51');

    expect(tx.addInput(hash, 7, 0xfffffffe, script)).toBe(0);
    expect(tx.ins[0]).toEqual({
      hash,
      index: 7,
      script,
      sequence: 0xfffffffe,
      witness: [],
    });

    expect(tx.addInput(h('cd'.repeat(32)), 0)).toBe(1);
    expect(tx.ins[1].sequence).toBe(Transaction.DEFAULT_SEQUENCE);
    expect(tx.ins[1].script).toEqual(EMPTY);
    expect(tx.ins[1].witness).toEqual([]);

    expect(tx.addInput(h('ef'.repeat(32)), 0, null, null)).toBe(2);
    expect(tx.ins[2].sequence).toBe(Transaction.DEFAULT_SEQUENCE);
    expect(tx.ins[2].script).toEqual(EMPTY);
  });

  test('addInput rejects malformed hashes and out-of-range or non-integer indexes', () => {
    const tx = new Transaction();
    const hash = h('00'.repeat(32));

    expect(() => tx.addInput(new Uint8Array(31), 0)).toThrow(/Expected 32 but received 31/);
    expect(() => tx.addInput(new Uint8Array(33), 0)).toThrow(/Expected 32 but received 33/);
    expect(() => tx.addInput('00'.repeat(32), 0)).toThrow(/Expected Uint8Array/);
    expect(() => tx.addInput(hash, -1)).toThrow(/Expected >=0/);
    expect(() => tx.addInput(hash, 0x100000000)).toThrow(/Expected <=4294967295/);
    expect(() => tx.addInput(hash, 1.5)).toThrow(/Invalid integer/);
    expect(() => tx.addInput(hash, 0, -1)).toThrow(/Expected >=0/);
    expect(() => tx.addInput(hash, 0, 0x100000000)).toThrow(/Expected <=4294967295/);
    expect(() => tx.addInput(hash, 0, 0, 'script')).toThrow(/Expected Uint8Array/);
  });

  test('addOutput stores satoshi values as bigint and returns its index', () => {
    const tx = new Transaction();
    const firstScript = h('6a');
    const secondScript = new Uint8Array(0);

    expect(tx.addOutput(firstScript, 0n)).toBe(0);
    expect(tx.addOutput(secondScript, 0x7fffffffffffffffn)).toBe(1);
    expect(tx.outs).toEqual([
      { script: firstScript, value: 0n },
      { script: secondScript, value: 0x7fffffffffffffffn },
    ]);
  });

  test('addOutput rejects invalid scripts and out-of-range satoshi values', () => {
    const tx = new Transaction();

    expect(() => tx.addOutput('6a', 1n)).toThrow(/Expected Uint8Array/);
    expect(() => tx.addOutput(h('6a'), 1)).toThrow(/Expected bigint/);
    expect(() => tx.addOutput(h('6a'), -1n)).toThrow(/Expected >=0/);
    expect(() => tx.addOutput(h('6a'), 0x8000000000000000n)).toThrow(
      /Expected <=9223372036854775807/,
    );
    expect(tx.outs).toEqual([]);
  });

  test('setInputScript and setWitness replace data and validate argument types', () => {
    const tx = new Transaction();
    tx.addInput(h('11'.repeat(32)), 0);
    tx.addInput(h('22'.repeat(32)), 1);

    tx.setInputScript(1, h('5152'));
    expect(hx(tx.ins[1].script)).toBe('5152');

    tx.setWitness(0, [h('aa'), h('bbcc')]);
    expect(tx.ins[0].witness.map(hx)).toEqual(['aa', 'bbcc']);

    tx.setWitness(0, []);
    expect(tx.ins[0].witness).toEqual([]);

    expect(() => tx.setInputScript(0, '51')).toThrow(/Expected Uint8Array/);
    expect(() => tx.setWitness(0, ['aa'])).toThrow(/Expected Uint8Array/);
    expect(() => tx.setWitness(0, null)).toThrow(/Expected an array/);
  });

  test('isCoinbaseHash only accepts a 32-byte all-zero array', () => {
    expect(Transaction.isCoinbaseHash(new Uint8Array(32))).toBe(true);

    const nonZero = new Uint8Array(32);
    nonZero[31] = 1;
    expect(Transaction.isCoinbaseHash(nonZero)).toBe(false);

    expect(() => Transaction.isCoinbaseHash(new Uint8Array(31))).toThrow(
      /Expected 32 but received 31/,
    );
  });

  test('isCoinbase requires exactly one input spending the null outpoint', () => {
    const tx = new Transaction();
    expect(tx.isCoinbase()).toBe(false);

    tx.addInput(new Uint8Array(32), 0xffffffff);
    expect(tx.isCoinbase()).toBe(true);

    tx.addInput(new Uint8Array(32), 0xffffffff);
    expect(tx.isCoinbase()).toBe(false);

    const nonCoinbase = new Transaction();
    nonCoinbase.addInput(h('01'.repeat(32)), 0);
    expect(nonCoinbase.isCoinbase()).toBe(false);
  });

  test('hasWitnesses tracks any non-empty input witness and stripWitnesses clears all of them', () => {
    const tx = new Transaction();
    tx.addInput(h('01'.repeat(32)), 0);
    tx.addInput(h('02'.repeat(32)), 1);

    expect(tx.hasWitnesses()).toBe(false);
    tx.setWitness(1, []);
    expect(tx.hasWitnesses()).toBe(false);
    tx.setWitness(0, [h('aa'), h('bb')]);
    expect(tx.hasWitnesses()).toBe(true);

    tx.stripWitnesses();
    expect(tx.hasWitnesses()).toBe(false);
    expect(tx.ins[0].witness).toEqual([]);
    expect(tx.ins[1].witness).toEqual([]);
  });
});

describe('Transaction sizing and cloning', () => {
  test('computes byte length, weight, and virtual size for an empty transaction', () => {
    const tx = new Transaction();

    expect(tx.byteLength()).toBe(10);
    expect(tx.byteLength(false)).toBe(10);
    expect(tx.weight()).toBe(40);
    expect(tx.virtualSize()).toBe(10);
  });

  test('accounts for witness data and varint script length boundaries', () => {
    const tx = makeSampleTx();

    expect(tx.byteLength()).toBe(74);
    expect(tx.byteLength(false)).toBe(63);
    expect(tx.weight()).toBe(263);
    expect(tx.virtualSize()).toBe(66);

    const boundaryTx = new Transaction();
    boundaryTx.addOutput(new Uint8Array(252), 0n);
    expect(boundaryTx.byteLength(false)).toBe(271);
    boundaryTx.outs[0].script = new Uint8Array(253);
    expect(boundaryTx.byteLength(false)).toBe(274);
  });

  test('clone copies transaction state into independent containers', () => {
    const tx = makeSampleTx();
    const clone = tx.clone();

    expect(clone).toBeInstanceOf(Transaction);
    expect(clone).not.toBe(tx);
    expect(clone.toHex()).toBe(tx.toHex());
    expect(clone.ins).not.toBe(tx.ins);
    expect(clone.outs).not.toBe(tx.outs);
    expect(clone.ins[0]).not.toBe(tx.ins[0]);
    expect(clone.outs[0]).not.toBe(tx.outs[0]);

    clone.version = 3;
    clone.locktime = 99;
    clone.ins[0].index = 1;
    clone.ins[0].sequence = 2;
    clone.outs[0].value = 1n;
    clone.ins.push({ ...clone.ins[0] });
    clone.outs.push({ script: EMPTY, value: 0n });

    expect(tx.version).toBe(2);
    expect(tx.locktime).toBe(0x01020304);
    expect(tx.ins).toHaveLength(1);
    expect(tx.ins[0].index).toBe(0x11223344);
    expect(tx.ins[0].sequence).toBe(0xaabbccdd);
    expect(tx.outs).toHaveLength(1);
    expect(tx.outs[0].value).toBe(123456789n);
    expect(tx.toHex()).toBe(SAMPLE_TX_HEX);
  });
});

describe('Transaction serialization and parsing', () => {
  test('serializes a witness transaction to its exact byte representation', () => {
    const tx = makeSampleTx();
    const buffer = tx.toBuffer();

    expect(buffer).toBeInstanceOf(Uint8Array);
    expect(buffer).toHaveLength(74);
    expect(hx(buffer)).toBe(SAMPLE_TX_HEX);
    expect(tx.toHex()).toBe(SAMPLE_TX_HEX);
  });

  test('round-trips all transaction fields including witness stacks', () => {
    const parsed = Transaction.fromHex(SAMPLE_TX_HEX);

    expect(parsed.version).toBe(2);
    expect(parsed.locktime).toBe(0x01020304);
    expect(parsed.ins).toHaveLength(1);
    expect(hx(parsed.ins[0].hash)).toBe('07'.repeat(32));
    expect(parsed.ins[0].index).toBe(0x11223344);
    expect(parsed.ins[0].script).toEqual(h('5152'));
    expect(parsed.ins[0].sequence).toBe(0xaabbccdd);
    expect(parsed.ins[0].witness.map(hx)).toEqual(['aabb', 'ccddeeff']);
    expect(parsed.outs).toHaveLength(1);
    expect(parsed.outs[0].value).toBe(123456789n);
    expect(parsed.outs[0].script).toEqual(h('6a'));
    expect(parsed.toHex()).toBe(SAMPLE_TX_HEX);
  });

  test('supports writing at an initial offset without overwriting surrounding bytes', () => {
    const tx = makeSampleTx();
    const destination = new Uint8Array(SAMPLE_TX_HEX.length / 2 + 7);
    destination.fill(0xee);

    const written = tx.toBuffer(destination, 3);

    expect(hx(written)).toBe(SAMPLE_TX_HEX);
    expect(hx(destination.slice(0, 3))).toBe('eeeeee');
    expect(hx(destination.slice(3 + written.length))).toBe('eeeeeeee');
  });

  test('returns the whole supplied buffer when no initial offset is given', () => {
    const tx = makeSampleTx();
    const destination = new Uint8Array(74);
    const result = tx.toBuffer(destination);

    expect(result).toBe(destination);
    expect(hx(result)).toBe(SAMPLE_TX_HEX);
  });

  test('strict parsing rejects trailing data while _NO_STRICT accepts it', () => {
    const withTrailingByte = SAMPLE_TX_HEX + 'ff';
    const buffer = h(withTrailingByte);

    expect(() => Transaction.fromBuffer(buffer)).toThrow('Transaction has unexpected data');
    const parsed = Transaction.fromBuffer(buffer, true);
    expect(parsed.toHex()).toBe(SAMPLE_TX_HEX);
  });

  test('rejects a witness-marked transaction containing only empty witnesses', () => {
    const emptyWitnessTx =
      '01000000000101' + '00'.repeat(32) + '0000000000ffffffff0000000000000000';

    expect(() => Transaction.fromHex(emptyWitnessTx)).toThrow(
      'Transaction has superfluous witness data',
    );
  });

  test('preserves the canonical genesis coinbase transaction byte-for-byte', () => {
    const tx = Transaction.fromHex(GENESIS_TX_HEX);

    expect(tx.version).toBe(1);
    expect(tx.locktime).toBe(0);
    expect(tx.ins).toHaveLength(1);
    expect(tx.outs).toHaveLength(1);
    expect(tx.outs[0].value).toBe(5000000000n);
    expect(tx.isCoinbase()).toBe(true);
    expect(tx.toHex()).toBe(GENESIS_TX_HEX);
  });
});

describe('Transaction hashes and IDs', () => {
  test('computes the known genesis txid in display byte order', () => {
    const tx = Transaction.fromHex(GENESIS_TX_HEX);

    expect(tx.getId()).toBe(
      '4a5e1e4baab89f3a32518a88c31bc87f618f76673e2cc77ab2127b7afdeda33b',
    );
    expect(hx(tx.getHash(false))).toBe(
      '3ba3edfd7a7b12b27ac72c3e67768f617fc81bc3888a51323a9fb8aa4b1e5e4a',
    );
    expect(hx(tx.getHash(true))).toBe('00'.repeat(32));
    expect(tx.byteLength()).toBe(204);
    expect(tx.weight()).toBe(816);
    expect(tx.virtualSize()).toBe(204);
  });

  test('witness data changes the wtxid but not the txid', () => {
    const tx = new Transaction();
    tx.version = 2;
    tx.addInput(h('42'.repeat(32)), 3);
    tx.addOutput(h('51'), 1000n);

    const txidBefore = tx.getId();
    const hashBefore = hx(tx.getHash(false));
    const wtxidBefore = hx(tx.getHash(true));

    tx.setWitness(0, [h('deadbeef')]);

    expect(tx.getId()).toBe(txidBefore);
    expect(hx(tx.getHash(false))).toBe(hashBefore);
    expect(hx(tx.getHash(true))).not.toBe(wtxidBefore);
    expect(tx.getId()).toHaveLength(64);
  });
});

describe('Legacy signature hashing', () => {
  test('matches canonical legacy SIGHASH_ALL results and ignores OP_CODESEPARATOR', () => {
    const tx = Transaction.fromHex(LEGACY_SIGHASH_TX_HEX);
    const plainScript = bscript.fromASM('OP_0 OP_3');
    const separatedScript = bscript.fromASM('OP_0 OP_CODESEPARATOR OP_3');

    const plainHash = tx.hashForSignature(0, plainScript, Transaction.SIGHASH_ALL);
    const separatedHash = tx.hashForSignature(
      0,
      separatedScript,
      Transaction.SIGHASH_ALL,
    );

    expect(plainHash).toHaveLength(32);
    expect(hx(plainHash)).toBe(
      '3d56a632462b9fc9b89eeddcad7dbe476297f34aff7e5f9320e2a99fb5e97136',
    );
    expect(separatedHash).toEqual(plainHash);
    expect(
      hx(tx.hashForSignature(0, bscript.fromASM('OP_0 OP_4'), Transaction.SIGHASH_ALL)),
    ).toBe('fa075877cb54916236806a6562e4a8cdad48adf1268e73d72d1f9fdd867df463');
  });

  test('returns the one-hash sentinel for out-of-range indexes', () => {
    const tx = Transaction.fromHex(LEGACY_SIGHASH_TX_HEX);
    const script = bscript.fromASM('OP_0');

    expect(tx.hashForSignature(2, script, Transaction.SIGHASH_ALL)).toEqual(ONE_HASH);
    expect(tx.hashForSignature(2, script, Transaction.SIGHASH_SINGLE)).toEqual(ONE_HASH);
    expect(ONE_HASH).toHaveLength(32);
  });

  test('applies SIGHASH_NONE and ANYONECANPAY without mutating the transaction', () => {
    const tx = Transaction.fromHex(LEGACY_SIGHASH_TX_HEX);
    const script = bscript.fromASM('OP_0 OP_3');
    const originalHex = tx.toHex();
    const allHash = hx(tx.hashForSignature(0, script, Transaction.SIGHASH_ALL));
    const noneHash = hx(tx.hashForSignature(0, script, Transaction.SIGHASH_NONE));
    const allAnyoneHash = hx(
      tx.hashForSignature(
        0,
        script,
        Transaction.SIGHASH_ALL | Transaction.SIGHASH_ANYONECANPAY,
      ),
    );

    expect(allHash).not.toBe(noneHash);
    expect(allHash).not.toBe(allAnyoneHash);

    const changedOutput = tx.clone();
    changedOutput.outs[0].value += 1n;
    expect(hx(changedOutput.hashForSignature(0, script, Transaction.SIGHASH_NONE))).toBe(
      noneHash,
    );
    expect(hx(changedOutput.hashForSignature(0, script, Transaction.SIGHASH_ALL))).not.toBe(
      allHash,
    );

    const changedOtherInput = tx.clone();
    changedOtherInput.ins[1].hash = new Uint8Array(32).fill(9);
    expect(
      hx(
        changedOtherInput.hashForSignature(
          0,
          script,
          Transaction.SIGHASH_ALL | Transaction.SIGHASH_ANYONECANPAY,
        ),
      ),
    ).toBe(allAnyoneHash);
    expect(
      hx(changedOtherInput.hashForSignature(0, script, Transaction.SIGHASH_ALL)),
    ).not.toBe(allHash);
    expect(tx.toHex()).toBe(originalHex);
  });

  test('validates the input index, previous output script, and hash type', () => {
    const tx = Transaction.fromHex(LEGACY_SIGHASH_TX_HEX);
    const script = bscript.fromASM('OP_0');

    expect(() => tx.hashForSignature(-1, script, Transaction.SIGHASH_ALL)).toThrow(
      /Expected >=0/,
    );
    expect(() => tx.hashForSignature(0, '51', Transaction.SIGHASH_ALL)).toThrow(
      /Expected Uint8Array/,
    );
    expect(() => tx.hashForSignature(0, script, '1')).toThrow(/Expected number/);
  });
});

describe('BIP143 signature hashing', () => {
  test('matches the canonical native P2WPKH signature hash', () => {
    const tx = makeBip143Tx();
    const hash = tx.hashForWitnessV0(
      1,
      BIP143_SCRIPT,
      600000000n,
      Transaction.SIGHASH_ALL,
    );

    expect(hash).toHaveLength(32);
    expect(hx(hash)).toBe(
      'c37af31116d1b27caf68aae9e3ac82f1477929014d5b917657d0eb49478cb670',
    );
  });

  test('binds the amount, outputs, and other inputs according to hash type', () => {
    const tx = makeBip143Tx();
    const allHash = hx(tx.hashForWitnessV0(1, BIP143_SCRIPT, 600000000n, 1));
    const noneHash = hx(tx.hashForWitnessV0(1, BIP143_SCRIPT, 600000000n, 2));
    const singleHash = hx(tx.hashForWitnessV0(1, BIP143_SCRIPT, 600000000n, 3));
    const allAnyoneHash = hx(tx.hashForWitnessV0(1, BIP143_SCRIPT, 600000000n, 0x81));

    expect(hx(tx.hashForWitnessV0(1, BIP143_SCRIPT, 600000001n, 1))).not.toBe(allHash);
    expect(allHash).not.toBe(noneHash);
    expect(allHash).not.toBe(singleHash);
    expect(allHash).not.toBe(allAnyoneHash);

    const changedFirstOutput = tx.clone();
    changedFirstOutput.outs[0].value += 1n;
    expect(
      hx(changedFirstOutput.hashForWitnessV0(1, BIP143_SCRIPT, 600000000n, 2)),
    ).toBe(noneHash);
    expect(
      hx(changedFirstOutput.hashForWitnessV0(1, BIP143_SCRIPT, 600000000n, 3)),
    ).toBe(singleHash);
    expect(
      hx(changedFirstOutput.hashForWitnessV0(1, BIP143_SCRIPT, 600000000n, 1)),
    ).not.toBe(allHash);

    const changedSecondOutput = tx.clone();
    changedSecondOutput.outs[1].value += 1n;
    expect(
      hx(changedSecondOutput.hashForWitnessV0(1, BIP143_SCRIPT, 600000000n, 3)),
    ).not.toBe(singleHash);

    const changedOtherInput = tx.clone();
    changedOtherInput.ins[0].sequence = 0;
    expect(
      hx(changedOtherInput.hashForWitnessV0(1, BIP143_SCRIPT, 600000000n, 0x81)),
    ).toBe(allAnyoneHash);
    expect(
      hx(changedOtherInput.hashForWitnessV0(1, BIP143_SCRIPT, 600000000n, 1)),
    ).not.toBe(allHash);
  });

  test('rejects invalid argument types', () => {
    const tx = makeBip143Tx();

    expect(() => tx.hashForWitnessV0(-1, BIP143_SCRIPT, 1n, 1)).toThrow(/Expected >=0/);
    expect(() => tx.hashForWitnessV0(1, 'script', 1n, 1)).toThrow(
      /Expected Uint8Array/,
    );
    expect(() => tx.hashForWitnessV0(1, BIP143_SCRIPT, 1, 1)).toThrow(
      /Expected bigint/,
    );
    expect(() => tx.hashForWitnessV0(1, BIP143_SCRIPT, 1n, 0x100000000)).toThrow(
      /Expected <=4294967295/,
    );
  });
});

describe('BIP341 signature hashing', () => {
  test.each([
    [0, 0x03, '7e584883b084ace0469c6962a9a7d2a9060e1f3c218ab40d32c77651482122bc'],
    [1, 0x83, '325a644af47e8a5a2591cda0ab0723978537318f10e6a63d4eed783b96a71a4d'],
    [3, 0x01, '6ffd256e108685b41831385f57eebf2fca041bc6b5e607ea11b3e03d4cf9d9ba'],
    [4, 0x00, '9f90136737540ccc18707e1fd398ad222a1a7e4dd65cbfd22dbe4660191efa58'],
    [6, 0x02, '835c9ab6084ed9a8ae9b7cda21e0aa797aca3b76a54bd1e3c7db093f6c57e23f'],
    [7, 0x82, 'df1cca638283c667084b8ffe6bf6e116cc5a53cf7ae1202c5fee45a9085f1ba5'],
    [8, 0x81, '30319859ca79ea1b7a9782e9daebc46e4ca4ca2bc04c9c53b2ec87fa83a526bd'],
  ])('matches canonical BIP341 vector for input %i and hash type 0x%s', (vin, type, expected) => {
    const { tx, scripts, values } = makeTaprootContext();
    const hash = tx.hashForWitnessV1(vin, scripts, values, type);

    expect(hash).toHaveLength(32);
    expect(hx(hash)).toBe(expected);
  });

  test('incorporates optional annex and tapleaf data deterministically', () => {
    const { tx, scripts, values } = makeTaprootContext();
    const leafHash = new Uint8Array(32).fill(0x11);
    const annex = h('50aa');

    const base = hx(tx.hashForWitnessV1(0, scripts, values, 0));
    const repeated = hx(tx.hashForWitnessV1(0, scripts, values, 0));
    const withLeaf = hx(tx.hashForWitnessV1(0, scripts, values, 0, leafHash));
    const withAnnex = hx(
      tx.hashForWitnessV1(0, scripts, values, 0, undefined, annex),
    );
    const withBoth = hx(tx.hashForWitnessV1(0, scripts, values, 0, leafHash, annex));

    expect(repeated).toBe(base);
    expect(new Set([base, withLeaf, withAnnex, withBoth]).size).toBe(4);
  });

  test('requires a previous output script and value for every input', () => {
    const { tx, scripts, values } = makeTaprootContext();

    expect(() => tx.hashForWitnessV1(0, scripts.slice(1), values, 1)).toThrow(
      'Must supply prevout script and value for all inputs',
    );
    expect(() => tx.hashForWitnessV1(0, scripts, values.slice(1), 1)).toThrow(
      'Must supply prevout script and value for all inputs',
    );
  });

  test('requires outputs for output-committing hash types but permits wildcard types', () => {
    const tx = new Transaction();
    tx.addInput(h('01'.repeat(32)), 0);

    expect(() => tx.hashForWitnessV1(0, [EMPTY], [0n], 1)).toThrow(
      'Add outputs to the transaction before signing.',
    );
    expect(() => tx.hashForWitnessV1(0, [EMPTY], [0n], 0)).toThrow(
      'Add outputs to the transaction before signing.',
    );
    expect(tx.hashForWitnessV1(0, [EMPTY], [0n], 2)).toHaveLength(32);
    expect(tx.hashForWitnessV1(0, [EMPTY], [0n], 3)).toHaveLength(32);
  });

  test('validates hash arguments', () => {
    const { tx, scripts, values } = makeTaprootContext();

    expect(() => tx.hashForWitnessV1(-1, scripts, values, 1)).toThrow(/Expected >=0/);
    expect(() => tx.hashForWitnessV1(0, [1], values, 1)).toThrow(
      /Expected Uint8Array/,
    );
    expect(() => tx.hashForWitnessV1(0, scripts, [1], 1)).toThrow(/Expected bigint/);
    expect(() => tx.hashForWitnessV1(0, scripts, values, -1)).toThrow(/Expected >=0/);
  });
});
