    expect(() => tx.hashForWitnessV1(0, scripts, values.slice(1), 1)).toThrow(
      'Must supply prevout script and value for all inputs',
    );
  });

  test('requires outputs for output-committing hash types but permits wildcard types', () => {
    const tx = new Transaction();
    tx.addInput(h('01'.repeat(32)), 0);

    expect(() => tx.hashForWitnessV1(0, [EMPTY], [0n], 1)).toThrow(
      'Add outputs to the transaction before signing.',
    );
    expect(() => tx.hashForWitnessV1(0, [EMPTY], [0n], 0)).toThrow(
      'Add outputs to the transaction before signing.',
    );
    expect(tx.hashForWitnessV1(0, [EMPTY], [0n], 2)).toHaveLength(32);
    expect(tx.hashForWitnessV1(0, [EMPTY], [0n], 3)).toHaveLength(32);
  });

  test('validates hash arguments', () => {
    const { tx, scripts, values } = makeTaprootContext();

    expect(() => tx.hashForWitnessV1(-1, scripts, values, 1)).toThrow(/Expected >=0/);
    expect(() => tx.hashForWitnessV1(0, [1], values, 1)).toThrow(
